//go:build ignore

package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

type symbolKey struct {
	pkgPath  string
	name     string
	file     string
	line     int
	recvType string
}

type callRecord struct {
	callerFile string
	callerLine int
}

func main() {
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedFiles | packages.NeedSyntax |
			packages.NeedTypes | packages.NeedTypesInfo | packages.NeedDeps,
		Dir:  "/bench/repo",
		Tests: true,
	}
	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		fmt.Fprintf(os.Stderr, "load: %v\n", err)
		os.Exit(1)
	}
	if packages.PrintErrors(pkgs) > 0 {
		os.Exit(1)
	}

	repoRoot := "/bench/repo"
	isTestFile := func(f string) bool {
		return strings.HasSuffix(filepath.Base(f), "_test.go")
	}
	isInternalDecl := func(f string) bool {
		rel, err := filepath.Rel(repoRoot, f)
		if err != nil {
			return false
		}
		return strings.HasPrefix(rel, "internal"+string(filepath.Separator)) ||
			strings.HasPrefix(rel, "internal/")
	}

	decls := map[symbolKey]token.Pos{}
	objToKey := map[interface{}]symbolKey{}

	for _, pkg := range pkgs {
		for i, f := range pkg.Syntax {
			filePath := compiledFile(pkg, i)
			if !isInternalDecl(filePath) {
				continue
			}
			ast.Inspect(f, func(n ast.Node) bool {
				fd, ok := n.(*ast.FuncDecl)
				if !ok || fd.Name == nil || fd.Name.Name == "init" {
					return true
				}
				pos := pkg.Fset.Position(fd.Pos())
				key := symbolKey{
					pkgPath: pkg.PkgPath,
					name:    fd.Name.Name,
					file:    pos.Filename,
					line:    pos.Line,
				}
				if fd.Recv != nil && len(fd.Recv.List) > 0 {
					key.recvType = exprString(fd.Recv.List[0].Type)
					key.name = fmt.Sprintf("(%s).%s", key.recvType, fd.Name.Name)
				}
				decls[key] = fd.Pos()
				if obj := pkg.TypesInfo.Defs[fd.Name]; obj != nil {
					objToKey[obj] = key
				}
				return true
			})
		}
	}

	allCalls := map[symbolKey][]callRecord{}
	prodCalls := map[symbolKey][]callRecord{}

	for _, pkg := range pkgs {
		for i, f := range pkg.Syntax {
			callerFile := compiledFile(pkg, i)
			callerIsTest := isTestFile(callerFile)

			ast.Inspect(f, func(n ast.Node) bool {
				call, ok := n.(*ast.CallExpr)
				if !ok {
					return true
				}
				callerPos := pkg.Fset.Position(call.Pos())

				var key symbolKey
				var found bool

				switch fun := call.Fun.(type) {
				case *ast.SelectorExpr:
					if obj := pkg.TypesInfo.Uses[fun.Sel]; obj != nil {
						if k, ok := objToKey[obj]; ok {
							key, found = k, true
						}
					}
				case *ast.Ident:
					if obj := pkg.TypesInfo.Uses[fun]; obj != nil {
						if k, ok := objToKey[obj]; ok {
							key, found = k, true
						}
					}
				}

				if !found {
					return true
				}

				rec := callRecord{callerFile: callerPos.Filename, callerLine: callerPos.Line}
				allCalls[key] = append(allCalls[key], rec)
				if !callerIsTest {
					prodCalls[key] = append(prodCalls[key], rec)
				}
				return true
			})
		}
	}

	type result struct {
		key       symbolKey
		allCount  int
		prodCount int
		callers   []callRecord
	}

	var results []result
	for k := range decls {
		results = append(results, result{
			key:       k,
			allCount:  len(allCalls[k]),
			prodCount: len(prodCalls[k]),
			callers:   allCalls[k],
		})
	}

	fmt.Println("=== TOP 30 by production call count ===")
	sort.Slice(results, func(i, j int) bool {
		if results[i].prodCount != results[j].prodCount {
			return results[i].prodCount > results[j].prodCount
		}
		return results[i].allCount > results[j].allCount
	})
	for i, r := range results {
		if i >= 30 {
			break
		}
		printResult(i+1, r, repoRoot)
	}

	fmt.Println("=== TOP 30 by all-code call count ===")
	sort.Slice(results, func(i, j int) bool {
		if results[i].allCount != results[j].allCount {
			return results[i].allCount > results[j].allCount
		}
		return results[i].prodCount > results[j].prodCount
	})
	for i, r := range results {
		if i >= 30 {
			break
		}
		printResult(i+1, r, repoRoot)
	}

	fmt.Printf("Total internal declarations: %d\n", len(decls))
}

func compiledFile(pkg *packages.Package, i int) string {
	if i < len(pkg.CompiledGoFiles) {
		return pkg.CompiledGoFiles[i]
	}
	if i < len(pkg.GoFiles) {
		return pkg.GoFiles[i]
	}
	return ""
}

func printResult(rank int, r result, repoRoot string) {
	rel, _ := filepath.Rel(repoRoot, r.key.file)
	fmt.Printf("%d. %s %s\n   def: %s:%d\n   prod=%d all=%d\n",
		rank, r.key.pkgPath, r.key.name, rel, r.key.line, r.prodCount, r.allCount)
	showCallers(r.callers, repoRoot, 10)
	fmt.Println()
}

type result struct {
	key       symbolKey
	allCount  int
	prodCount int
	callers   []callRecord
}

func showCallers(callers []callRecord, repoRoot string, limit int) {
	type loc struct {
		file string
		line int
		cnt  int
	}
	m := map[string]*loc{}
	for _, c := range callers {
		k := fmt.Sprintf("%s:%d", c.callerFile, c.callerLine)
		if m[k] == nil {
			m[k] = &loc{file: c.callerFile, line: c.callerLine}
		}
		m[k].cnt++
	}
	var locs []*loc
	for _, l := range m {
		locs = append(locs, l)
	}
	sort.Slice(locs, func(i, j int) bool {
		if locs[i].cnt != locs[j].cnt {
			return locs[i].cnt > locs[j].cnt
		}
		return locs[i].file < locs[j].file
	})
	fmt.Print("   callers: ")
	shown := 0
	for _, l := range locs {
		if shown >= limit {
			fmt.Printf("... +%d more sites", len(locs)-limit)
			break
		}
		rel, _ := filepath.Rel(repoRoot, l.file)
		if shown > 0 {
			fmt.Print("; ")
		}
		if l.cnt > 1 {
			fmt.Printf("%s:%d(x%d)", rel, l.line, l.cnt)
		} else {
			fmt.Printf("%s:%d", rel, l.line)
		}
		shown++
	}
	fmt.Println()
}

func exprString(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		return "*" + exprString(t.X)
	case *ast.SelectorExpr:
		return exprString(t.X) + "." + t.Sel.Name
	default:
		return "?"
	}
}

