#!/usr/bin/perl
use strict;
use warnings;
use File::Find;
use File::Basename;
use Cwd 'abs_path';

my $REPO = '/bench/repo';
my $MODULE = 'github.com/usememos/memos';

# --- strip Go comments and strings, return cleaned source preserving newlines ---
sub strip_go {
    my ($src) = @_;
    my $out = '';
    my $i = 0;
    my $len = length($src);
    while ($i < $len) {
        my $c = substr($src, $i, 1);
        my $c2 = ($i + 1 < $len) ? substr($src, $i + 1, 1) : '';
        if ($c eq '/' && $c2 eq '/') {
            $i += 2;
            while ($i < $len && substr($src, $i, 1) ne "\n") { $i++; }
            $out .= "\n" if $i < $len;
            next;
        }
        if ($c eq '/' && $c2 eq '*') {
            $i += 2;
            while ($i + 1 < $len && !(substr($src, $i, 1) eq '*' && substr($src, $i + 1, 1) eq '/')) {
                $out .= "\n" if substr($src, $i, 1) eq "\n";
                $i++;
            }
            $i += 2 if $i + 1 < $len;
            next;
        }
        if ($c eq '"') {
            $out .= ' ';
            $i++;
            while ($i < $len) {
                my $ch = substr($src, $i, 1);
                if ($ch eq '\\') { $i += 2; next; }
                if ($ch eq '"') { $i++; last; }
                $out .= "\n" if $ch eq "\n";
                $i++;
            }
            next;
        }
        if ($c eq '`') {
            $out .= ' ';
            $i++;
            while ($i < $len && substr($src, $i, 1) ne '`') {
                $out .= "\n" if substr($src, $i, 1) eq "\n";
                $i++;
            }
            $i++ if $i < $len;
            next;
        }
        if ($c eq "'" && $i + 2 < $len) {
            $out .= ' ';
            $i += 2;
            $i++ if $i < $len;
            next;
        }
        $out .= $c;
        $i++;
    }
    return $out;
}

sub is_test_file { $_[0] =~ /_test\.go$/ }
sub is_internal_file {
    my ($f) = @_;
    my $rel = $f; $rel =~ s/^\Q$REPO\E\/?//;
    return $rel =~ /^internal\//;
}

my @go_files;
find(sub {
    return unless /\.go$/;
    push @go_files, $File::Find::name;
}, $REPO);

# Parse each file
my %file_info;  # path => { pkg, imports => {alias=>path}, pkgpath, is_test, lines=>[] }

for my $f (@go_files) {
    open my $fh, '<', $f or die $!;
    my $raw = do { local $/; <$fh> };
    close $fh;
    my @raw_lines = split /\n/, $raw, -1;
    my $clean = strip_go($raw);
    my @lines = split /\n/, $clean, -1;

    my $pkg = '';
    my %imports; # local_name => full_import_path
    for my $line (@lines) {
        if ($line =~ /^\s*package\s+(\w+)/) { $pkg = $1; last; }
    }
    for my $line (@lines) {
        if ($line =~ /^\s*import\s+"([^"]+)"/) {
            my $p = $1;
            my $local = (split /\//, $p)[-1];
            $local =~ s/-//g; # rough
            $imports{$local} = $p;
        }
        if ($line =~ /^\s*import\s+\(/) { last; } # handled below
    }
    # multi-line import block
    if ($clean =~ /import\s*\((.*?)\)/s) {
        my $block = $1;
        while ($block =~ /(?:"([^"]+)"|(\w+)\s+"([^"]+)")/g) {
            if ($1) {
                my $p = $1;
                my $local = (split /\//, $p)[-1];
                $imports{$local} = $p;
            } elsif ($2 && $3) {
                $imports{$2} = $3;
            }
        }
    }

    # derive package path from file location
    my $rel = $f; $rel =~ s/^\Q$REPO\E\/?//;
    my $pkgpath = $MODULE . '/' . $rel;
    $pkgpath =~ s/\/[^\/]+\.go$//;

    $file_info{$f} = {
        pkg => $pkg,
        pkgpath => $pkgpath,
        imports => \%imports,
        is_test => is_test_file($f),
        lines => \@lines,
        raw_lines => \@raw_lines,
    };
}

# Collect internal declarations
# sym_id => { pkgpath, pkg, name, recv, file, line, qual }
my %decls;
my %decl_by_pkg_func;   # "$pkgpath\t$name" => sym_id (non-method)
my %decl_by_pkg_recv_method; # "$pkgpath\t$recv\t$method" => sym_id

my $sym_counter = 0;
for my $f (sort keys %file_info) {
    next unless is_internal_file($f);
    my $info = $file_info{$f};
    my $i = 0;
    for my $line (@{ $info->{lines} }) {
        $i++;
        if ($line =~ /^\s*func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(/) {
            # skip - need recv capture
        }
        if ($line =~ /^\s*func\s+\(([^)]*)\)\s+(\w+)\s*\(/) {
            my ($recv, $name) = ($1, $2);
            next if $name eq 'init';
            my $recv_type = extract_recv_type($recv);
            my $id = ++$sym_counter;
            my $qual = "($recv_type).$name";
            $decls{$id} = {
                pkgpath => $info->{pkgpath}, pkg => $info->{pkg},
                name => $name, recv => $recv_type, qual => $qual,
                file => $f, line => $i,
            };
            $decl_by_pkg_recv_method{"$info->{pkgpath}\t$recv_type\t$name"} = $id;
        }
        elsif ($line =~ /^\s*func\s+(\w+)\s*\(/) {
            my $name = $1;
            next if $name eq 'init';
            my $id = ++$sym_counter;
            $decls{$id} = {
                pkgpath => $info->{pkgpath}, pkg => $info->{pkg},
                name => $name, recv => '', qual => $name,
                file => $f, line => $i,
            };
            $decl_by_pkg_func{"$info->{pkgpath}\t$name"} = $id;
        }
    }
}

sub extract_recv_type {
    my ($recv) = @_;
    $recv =~ s/^\s*//; $recv =~ s/\s*$//;
    $recv =~ s/^[\w.]+\s+//; # remove var name
    $recv =~ s/^\*//;
    $recv =~ s/^interface\{\}$/interface{}/;
    return $recv;
}

# Count calls
my %all_calls;   # sym_id => [ {file, line}, ... ]
my %prod_calls;

for my $f (sort keys %file_info) {
    my $info = $file_info{$f};
    my $caller_is_test = $info->{is_test};
    my $i = 0;
    for my $line (@{ $info->{lines} }) {
        $i++;
        # Find call expressions: identifier( or selector.identifier(
        while ($line =~ /(?:^|[^\w.])([\w]+)\.([\w]+)\s*\(/g) {
            my ($sel, $callee) = ($1, $2);
            next if $callee =~ /^(if|for|switch|return|func|go|defer|make|new|len|cap|append|copy|delete|panic|recover|close|complex|real|imag|print|println)$/;
            my $id;
            if (exists $info->{imports}{$sel}) {
                my $import_path = $info->{imports}{$sel};
                $id = $decl_by_pkg_func{"$import_path\t$callee"};
            } elsif ($sel eq $info->{pkg}) {
                # same package via qualifier (rare)
                $id = $decl_by_pkg_func{"$info->{pkgpath}\t$callee"};
            } else {
                # method call sel.Method(
                $id = resolve_method_call($info, $sel, $callee, $line, $`);
            }
            record_call($id, $f, $i, $caller_is_test) if $id;
        }
        while ($line =~ /(?:^|[^\w.])([\w]+)\s*\(/g) {
            my $callee = $1;
            next if $callee =~ /^(if|for|switch|return|func|go|defer|make|new|len|cap|append|copy|delete|panic|recover|close|complex|real|imag|print|println|map|struct|interface)$/;
            my $id = $decl_by_pkg_func{"$info->{pkgpath}\t$callee"};
            record_call($id, $f, $i, $caller_is_test) if $id;
        }
    }
}

sub resolve_method_call {
    my ($info, $sel, $method, $line, $pos) = @_;
    # Try to find receiver type from variable declarations in this package
    # Fallback: match any internal method with this name in imported internal pkgs - too broad
    # Search all decls in same pkgpath with matching method name and check if sel variable type matches
    my $pkgpath = $info->{pkgpath};
    for my $id (keys %decls) {
        my $d = $decls{$id};
        next unless $d->{name} eq $method && $d->{recv};
        next unless $d->{pkgpath} eq $pkgpath || import_resolves_to($info, $d->{pkgpath});
        return $id if var_matches_type($info, $sel, $d->{recv}, $d->{pkgpath});
    }
    # Cross-package: if selector is imported package name, it's package.func not method
    return undef;
}

sub import_resolves_to {
    my ($info, $pkgpath) = @_;
    for my $p (values %{ $info->{imports} }) {
        return 1 if $p eq $pkgpath;
    }
    return 0;
}

# Simple type map: var => type within package (best effort)
my %pkg_var_types;

for my $f (keys %file_info) {
    my $info = $file_info{$f};
    my $pp = $info->{pkgpath};
    $pkg_var_types{$pp} ||= {};
    for my $line (@{ $info->{lines} }) {
        # var x Type, var x *Type
        while ($line =~ /(?:var|,\s*)(\w+)\s+(\*?)([\w.]+)/g) {
            $pkg_var_types{$pp}{$1} = ($2 ? '*' : '') . $3;
        }
        # x := &Type{}, x := Type{}, x := NewFoo()
        while ($line =~ /(\w+)\s*:?=\s*(\*?)\s*(?:&)?([\w]+)/g) {
            my ($v, $ptr, $t) = ($1, $2, $3);
            if ($t =~ /^[A-Z]/ || $t =~ /^New/) {
                my $type = $t;
                $type =~ s/^New//;
                $pkg_var_types{$pp}{$v} = ($ptr || (index($line, '&') >= 0 ? '*' : '')) . $type;
            }
        }
        # func (s *Type) patterns - param types
        while ($line =~ /(\w+)\s+(\*?)([\w.]+)\s*[,\)]/g) {
            # skip keywords
            next if $1 =~ /^(func|return|if|for)$/;
            $pkg_var_types{$pp}{$1} = ($2 ? '*' : '') . $3 unless $3 =~ /^(int|string|bool|error|byte|any|interface)$/;
        }
    }
}

sub var_matches_type {
    my ($info, $var, $recv_type, $decl_pkgpath) = @_;
    my $pp = $info->{pkgpath};
    # normalize recv - strip pointer for comparison
    my $rt = $recv_type; $rt =~ s/^\*//;
    for my $search_pp ($pp, keys %file_info) {
        next unless (grep { $_ eq $decl_pkgpath } ($search_pp, values %{ $file_info{$search_pp}{imports} }));
        my $vt = $pkg_var_types{$search_pp}{$var};
        next unless defined $vt;
        my $vtn = $vt; $vtn =~ s/^\*//;
        return 1 if $vtn eq $rt;
    }
    return 0;
}

sub record_call {
    my ($id, $file, $line, $is_test) = @_;
    return unless $id;
    push @{ $all_calls{$id} }, { file => $file, line => $line };
    push @{ $prod_calls{$id} }, { file => $file, line => $line } unless $is_test;
}

# Re-run method calls with better type info now that pkg_var_types is built
%all_calls = ();
%prod_calls = ();

for my $f (sort keys %file_info) {
    my $info = $file_info{$f};
    my $caller_is_test = $info->{is_test};
    my $i = 0;
    for my $line (@{ $info->{lines} }) {
        $i++;
        while ($line =~ /(?:^|[^\w.])([\w]+)\.([\w]+)\s*\(/g) {
            my ($sel, $callee) = ($1, $2);
            next if $callee =~ /^(if|for|switch|return|func|go|defer|make|new|len|cap|append|copy|delete|panic|recover|close)$/;
            my $id;
            if (exists $info->{imports}{$sel}) {
                my $import_path = $info->{imports}{$sel};
                $id = $decl_by_pkg_func{"$import_path\t$callee"};
            } else {
                # method call - resolve via type map across all packages that could be in scope
                $id = resolve_method_call_v2($info, $sel, $callee);
            }
            record_call($id, $f, $i, $caller_is_test) if $id;
        }
        while ($line =~ /(?:^|[^\w.])([\w]+)\s*\(/g) {
            my $callee = $1;
            next if $callee =~ /^(if|for|switch|return|func|go|defer|make|new|len|cap|append|copy|delete|panic|recover|close|complex|real|imag|print|println|map|struct|interface|uint|int|int32|int64|float32|float64|byte|rune|string|bool|error|any)$/;
            my $id = $decl_by_pkg_func{"$info->{pkgpath}\t$callee"};
            record_call($id, $f, $i, $caller_is_test) if $id;
        }
    }
}

sub resolve_method_call_v2 {
    my ($info, $var, $method) = @_;
    my @candidates;
    # Search internal decls with this method name
    for my $id (keys %decls) {
        my $d = $decls{$id};
        next unless $d->{name} eq $method && $d->{recv};
        push @candidates, $id;
    }
    return undef unless @candidates;
    return $candidates[0] if @candidates == 1;

    # Filter by variable type
    my @matched;
    for my $id (@candidates) {
        my $d = $decls{$id};
        if (var_matches_type_v2($info, $var, $d->{recv}, $d->{pkgpath})) {
            push @matched, $id;
        }
    }
    return $matched[0] if @matched == 1;
    # If same-package candidate exists and var type unknown, prefer same package
    for my $id (@candidates) {
        return $id if $decls{$id}{pkgpath} eq $info->{pkgpath};
    }
    return undef; # ambiguous
}

sub var_matches_type_v2 {
    my ($info, $var, $recv_type, $decl_pkgpath) = @_;
    my $rt = $recv_type; $rt =~ s/^\*//;
    # check local package vars
    my $vt = $pkg_var_types{$info->{pkgpath}}{$var};
    if (defined $vt) {
        my $vtn = $vt; $vtn =~ s/^\*//; $vtn =~ s/^.*\.//;
        return 1 if $vtn eq $rt;
    }
    # check if var is receiver name in scope - search function-local is hard; skip
    # check imported package prefix: pkg.Type method via embedding - skip
    # If decl is in imported package and var could be that type from constructor
    for my $alias (keys %{ $info->{imports} }) {
        next unless $info->{imports}{$alias} eq $decl_pkgpath;
        # var named with lowercase of type?
    }
    return 0;
}

# Sort and print
