        decl => $decls{$id},
        prod => scalar(@{ $prod_calls{$id} // [] }),
        all => scalar(@{ $all_calls{$id} // [] }),
        callers => $all_calls{$id} // [],
    };
}

sub print_top {
    my ($title, $sort_key) = @_;
