    }
    print " ... +" . (scalar(@locs) - 10) . " more" if scalar(@locs) > 10;
    print "\n";
}

print_top("TOP 30 by production", 'prod');
print_top("TOP 30 by all-code", 'all');
print "Total internal declarations: " . scalar(keys %decls) . "\n";

