        }
        if ($c eq '/' && $c2 eq '*') {
            $i += 2;
            while ($i + 1 < $len && !(substr($src, $i, 1) eq '*' && substr($src, $i + 1, 1) eq '/')) {
                $out .= "\n" if substr($src, $i, 1) eq "\n";
                $i++;
            }
            $i += 2 if $i + 1 < $len;
            next;
        }
        if ($c eq '"') {
            $out .= ' ';
            $i++;
            while ($i < $len) {
                my $ch = substr($src, $i, 1);
                if ($ch eq '\\') { $i += 2; next; }
                if ($ch eq '"') { $i++; last; }
                $out .= "\n" if $ch eq "\n";
