    }
}

sub show_callers {
    my ($callers) = @_;
    my %by_loc;
    for my $c (@$callers) {
        my $rel = $c->{file}; $rel =~ s/^\Q$REPO\E\/?//;
        $by_loc{"$rel:$c->{line}"}++;
