        print "; " if $shown++;
        print $by_loc{$loc} > 1 ? "$loc(x$by_loc{$loc})" : $loc;
    }
    print " ... +" . (scalar(@locs) - 10) . " more" if scalar(@locs) > 10;
    print "\n";
}

