    while ($c =~ /\bfunc\s+\((\w+)\s+(\*?)([\w.]+)\)/g) {
        my ($v, $ptr, $t) = ($1, $2, $3);
        $t =~ s/^.*\.//;
        $pkg_types{$pp}{$v} = ($ptr ? '*' : '') . $t;
    }
    # param types
    while ($c =~ /\bfunc\s+(?:\([^)]*\)\s+)?\w+\s*\(([^)]*)\)/g) {
        my $params = $1;
        while ($params =~ /(\w+)\s+(\*?)([\w.]+)/g) {
            my ($v, $ptr, $t) = ($1, $2, $3);
            next if $v =~ /^(ctx|context|err|error)$/;
            $t =~ s/^.*\.//;
            $pkg_types{$pp}{$v} = ($ptr ? '*' : '') . $t unless $t =~ /^(int|string|bool|error|byte|any|Context|interface)$/;
        }
    }
    # short declarations
    while ($c =~ /(\w+)\s*:?=\s*(?:&)?(\*?)\s*([\w]+)\(/g) {
        my ($v, $ptr, $ctor) = ($1, $2, $3);
        if ($ctor =~ /^New([A-Z]\w*)/) {
            $pkg_types{$pp}{$v} = ($ptr || '') . $1;
        }
    }
    while ($c =~ /(\w+)\s*:?=\s*(?:&)?(\*?)([A-Z]\w*)\{/g) {
        my ($v, $ptr, $t) = ($1, $2, $3);
        $pkg_types{$pp}{$v} = ($ptr ? '*' : '') . $t;
    }
    # var declarations
    while ($c =~ /\bvar\s+(\w+)\s+(\*?)([\w.]+)/g) {
        my ($v, $ptr, $t) = ($1, $2, $3);
        $t =~ s/^.*\.//;
        $pkg_types{$pp}{$v} = ($ptr ? '*' : '') . $t;
    }
}

my %all; my %prod;

sub bump {
    my ($id, $f, $line) = @_;
    return unless $id;
    push @{ $all{$id} }, [$f, $line];
    push @{ $prod{$id} }, [$f, $line] unless is_test($f);
}

# Reserved words / builtins to skip as callees
my %skip = map { $_ => 1 } qw(
    if for switch return func go defer make new len cap append copy delete
    panic recover close complex real imag print println map struct interface
    int int8 int16 int32 int64 uint uint8 uint16 uint32 uint64 float32 float64
    bool byte rune string error any true false nil
);

for my $f (keys %fi) {
    my $info = $fi{$f};
    my $pp = $info->{pkgpath};
    my $line_num = 0;
    for my $line (@{ $info->{lines} }) {
        $line_num++;

        # selector calls: pkg.Func or var.Method
        while ($line =~ /(?:^|[^\w.])([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
            my ($sel, $meth) = ($1, $2);
            next if $skip{$meth};

            my $id;
            if (exists $info->{imports}{$sel}) {
                my $ip = $info->{imports}{$sel};
                $id = $by_pkg_name{"$ip\t$meth"};
            } else {
                # method call - find matching recv type
                my $vt = $pkg_types{$pp}{$sel};
                if (defined $vt) {
                    my $rt = $vt; $rt =~ s/^\*//;
                    $id = $by_pkg_recv{"$pp\t$rt\t$meth"};
                    if (!$id) {
                        # search all internal packages for method on this type name
                        for my $did (keys %decls) {
                            my $d = $decls{$did};
                            next unless $d->{name} eq $meth && $d->{recv} eq $rt;
                            # prefer same package or imported package
                            if ($d->{pkgpath} eq $pp) { $id = $did; last; }
                            for my $a (keys %{ $info->{imports} }) {
                                if ($info->{imports}{$a} eq $d->{pkgpath}) { $id = $did; last; }
                            }
                            last if $id;
                        }
                    }
                }
            }
            bump($id, $f, $line_num);
        }

        # unqualified calls
        while ($line =~ /(?:^|[^\w.])([A-Za-z_]\w*)\s*\(/g) {
            my ($name) = $1;
            next if $skip{$name};
            my $id = $by_pkg_name{"$pp\t$name"};
            bump($id, $f, $line_num);
        }
    }
}

my @res;
for my $id (keys %decls) {
    push @res, {
        d => $decls{$id},
        prod => scalar(@{ $prod{$id} // [] }),
        all => scalar(@{ $all{$id} // [] }),
        callers => $all{$id} // [],
    };
}

@res = sort { $b->{prod} <=> $a->{prod} || $b->{all} <=> $a->{all} } @res;

print "=== TOP 40 production inbound calls to internal/ declarations ===\n";
for my $i (0..39) {
    last unless $i < @res;
    my $r = $res[$i];
    next if $r->{prod} == 0 && $r->{all} == 0;
    my $d = $r->{d};
    my $rel = $d->{file}; $rel =~ s/^\Q$REPO\E\/?//;
    printf "%d. %s :: %s\n   %s:%d  prod=%d all=%d\n",
        $i+1, $d->{pkgpath}, $d->{qual}, $rel, $d->{line}, $r->{prod}, $r->{all};
    show($r->{callers});
}

print "\n=== TOP 40 all-code ===\n";
@res = sort { $b->{all} <=> $a->{all} || $b->{prod} <=> $a->{prod} } @res;
for my $i (0..39) {
    last unless $i < @res;
    my $r = $res[$i];
    next if $r->{all} == 0;
    my $d = $r->{d};
    my $rel = $d->{file}; $rel =~ s/^\Q$REPO\E\/?//;
    printf "%d. %s :: %s\n   %s:%d  prod=%d all=%d\n",
        $i+1, $d->{pkgpath}, $d->{qual}, $rel, $d->{line}, $r->{prod}, $r->{all};
    show($r->{callers});
}

print "\nTotal internal decls: " . scalar(keys %decls) . "\n";

sub show {
    my ($cs) = @_;
    my %loc;
    for (@$cs) {
        my $rel = $_->[0]; $rel =~ s/^\Q$REPO\E\/?//;
        $loc{"$rel:$_->[1]"}++;
    }
    my @l = sort { $loc{$b} <=> $loc{$a} || $a cmp $b } keys %loc;
    print "   ";
    my $n = 0;
    for my $l (@l) {
        last if $n++ >= 12;
        print "; " if $n > 1;
        print $loc{$l} > 1 ? "$l(x$loc{$l})" : $l;
    }
    print " ..." if @l > 12;
    print "\n";
}

