#!/usr/bin/perl
use strict;
use warnings;

my $REPO = '/bench/repo';
my $MODULE = 'github.com/usememos/memos';

sub strip_go { my ($s)=@_; $s=~s/\/\/[^\n]*//g; $s=~s/\/\*.*?\*\///sg; $s=~s/`[^`]*`/ /g; $s=~s/"([^"\\]|\\.)*"/ /g; $s=~s/'[^']*'/ /g; return $s; }
sub is_test { $_[0]=~/_test\.go$/ }
sub rel { my $f=shift; $f=~s/^\Q$REPO\E\/?//; $f }

my @files = split /\n/, `find '$REPO' -name '*.go' -type f 2>/dev/null`;
chomp @files;

my %fi;
for my $f (@files) {
    open my $fh,'<',$f or die $f;
    my $raw=do{local $/;<$fh>}; close $fh;
    my $clean=strip_go($raw);
    my ($pkg) = $clean =~ /^\s*package\s+(\w+)/m;
    my %imp;
    if ($clean =~ /import\s*\((.*?)\)/s) {
        for my $line (split /\n/, $1) {
            if ($line =~ /^\s*(?:(\w+)\s+)?"([^"]+)"/) {
                my ($a,$p)=($1,$2);
                $a = (split/\//,$p)[-1] unless defined $a && $a ne '';
                $imp{$a}=$p;
            }
        }
    }
    while ($clean =~ /^\s*import\s+(?:(\w+)\s+)?"([^"]+)"/gm) {
        my ($a,$p)=($1,$2);
        $a = (split/\//,$p)[-1] unless defined $a && $a ne '';
        $imp{$a}=$p;
    }
    my $r=rel($f);
    my $pp=$MODULE.'/'.($r=~s/\/[^\/]+$//r);
    $fi{$f}={pkg=>$pkg,pp=>$pp,imp=>\%imp,clean=>$clean,test=>is_test($f)};
}

my (%decl,%by_name,%by_recv); my $id=0;
for my $f (@files) {
    next unless rel($f)=~/^internal\//;
    my $c=$fi{$f}{clean}; my $pp=$fi{$f}{pp};
    while ($c =~ /\bfunc\s+(?:\(([^)]*)\)\s+)?(\w+)\s*\(/g) {
        my ($recv,$name)=($1,$2); next if $name eq 'init';
        my $pos=pos($c); my $line=($c=~/.{0,$pos}/s=~tr/\n//)+1;
        my $rt=''; if(defined $recv && $recv ne ''){ $rt=$recv; $rt=~s/^[\w.]+\s+//; $rt=~s/^\*//; $rt=~s/^.*\.//; }
        my $sym=++$id;
        $decl{$sym}={pp=>$pp,name=>$name,rt=>$rt,file=>$f,line=>$line,qual=>($rt?"($rt).$name":$name)};
        $by_name{"$pp\t$name"}=$sym unless $rt;
        $by_recv{"$pp\t$rt\t$name"}=$sym if $rt;
    }
}

# type hints per package
my %types;
for my $f (keys %fi) {
    my $pp=$fi{$f}{pp}; $types{$pp}//={};
    my $c=$fi{$f}{clean};
    while ($c =~ /\bfunc\s+\((\w+)\s+(\*?)([\w.]+)\)/g) {
        my ($v,$p,$t)=($1,$2,$3); $t=~s/^.*\.//; $types{$pp}{$v}=($p?'*':'').$t;
    }
    while ($c =~ /\b(\w+)\s*:?=\s*(?:&)?(\*?)([A-Z]\w*)\{/g) {
        my ($v,$p,$t)=($1,$2,$3); $types{$pp}{$v}=($p?'*':'').$t;
    }
    while ($c =~ /\b(\w+)\s*:?=\s*(\w+)\.New([A-Z]\w*)\(/g) {
        my ($v,$imp,$t)=($1,$2,$3);
        if (exists $fi{$f}{imp}{$imp}) { $types{$pp}{$v}=$t; }
    }
    while ($c =~ /\bvar\s+(\w+)\s+(\*?)([\w.]+)/g) {
        my ($v,$p,$t)=($1,$2,$3); $t=~s/^.*\.//; $types{$pp}{$v}=($p?'*':'').$t;
    }
}

my (%all,%prod);
sub add { my ($s,$f,$l)=@_; return unless $s; push @{$all{$s}},[$f,$l]; push @{$prod{$s}},[$f,$l] unless $fi{$f}{test}; }

my %skip = map {$_=>1} qw(if for switch return func go defer make new len cap append copy delete panic recover close map struct interface int string bool error any);

for my $f (@files) {
    my $info=$fi{$f}; my $pp=$info->{pp}; my $ln=0;
    for my $line (split /\n/, $info->{clean}) {
        $ln++;
        while ($line =~ /(?:^|[^\w.])([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
            my ($sel,$m)=($1,$2); next if $skip{$m};
            my $s;
            if (exists $info->{imp}{$sel}) {
                $s = $by_name{"$info->{imp}{$sel}\t$m"};
            } else {
                my $vt = $types{$pp}{$sel}; $vt=~s/^\*// if defined $vt;
                if (defined $vt) {
                    $s = $by_recv{"$pp\t$vt\t$m"};
                    if (!$s) {
                        for my $sym (keys %decl) {
                            my $d=$decl{$sym};
                            next unless $d->{name} eq $m && $d->{rt} eq $vt;
                            for my $a (keys %{$info->{imp}}) {
                                if ($info->{imp}{$a} eq $d->{pp}) { $s=$sym; last; }
                            }
                            $s=$sym if !$s && $d->{pp} eq $pp;
                            last if $s;
                        }
                    }
                }
            }
            add($s,$f,$ln);
        }
        while ($line =~ /(?:^|[^\w.])([A-Za-z_]\w*)\s*\(/g) {
            my $m=$1; next if $skip{$m};
            add($by_name{"$pp\t$m"}, $f, $ln);
        }
    }
}

my @res = map { {d=>$decl{$_}, prod=>scalar(@{$prod{$_}//[]}), all=>scalar(@{$all{$_}//[]}), c=>$all{$_}//[]} } keys %decl;
@res = sort { $b->{prod}<=>$a->{prod} || $b->{all}<=>$a->{all} } @res;

print "TOP by production (non-_test.go callers):\n";
my $n=0; for my $r (@res) {
    next unless $r->{prod}>0 || $r->{all}>0;
    last if ++$n>35;
    my $d=$r->{d}; printf "%2d. %s :: %s @ %s:%d  prod=%d all=%d\n", $n,$d->{pp},$d->{qual},rel($d->{file}),$d->{line},$r->{prod},$r->{all};
    my %loc; $loc{"$_->[0]:$_->[1]"}++ for @{$r->{c}};
    my @l=sort { ($loc{$b}//0)<=>($loc{$a}//0) } keys %loc; my $k=0;
    print "    "; for my $x (@l[0..11]) { print "; " if $k++; my $rx=rel((split/:/,$x)[0]); print "$rx:".(split/:/,$x)[1]; }
    print "\n";
}
print "decls=", scalar(keys %decl), "\n";

# spot-check key symbols
for my $name (qw(GenUUID DefaultEngine AppendConditions NewEngine NewSchema NewService Validate ConvertStringToInt32 AllowAnonymous ValidateURL)) {
    for my $sym (keys %decl) {
        my $d=$decl{$sym}; next unless $d->{qual} eq $name;
        print "CHECK $name prod=$prod{$sym} all=$all{$sym} at ".rel($d->{file}).":$d->{line}\n";
    }
}

